create or replace view LDL_DATA_PRODUCTION.META.V_DV_OPEN_STORES_END_AND_BEGIN_WEEK_CNT_1(
	PART_WEEK,
	PART_WEEK_BEGIN_DT,
	PART_WEEK_END_DT,
	OPEN_RE_END_OF_WEEK_CNT,
	OPEN_RE_BEGIN_OF_WEEK_CNT,
	OPEN_RE_DURING_WEEK_CNT,
	CLOSED_RE_DURING_WEEK_CNT,
	DIFFERENCE,
	FAILED,
	TOTAL
) COMMENT='Open stores cnt at end of week should be equal to open stores cnt beginning of the week + opened stores during the week - closed stores during the week\ninput datasets:\ncore_dim.t_dim_calendar_partial_week_1\ncore_dim.t_dim_real_estate_1\ncore_dim.t_fact_real_estate_lifecycle_1'
 as WITH wk as ( SELECT part_week, part_week_begin_dt, part_week_end_dt FROM core_dim.t_dim_calendar_partial_week_1 WHERE part_week_offset = -1 ) select wk.part_week, wk.part_week_begin_dt, wk.part_week_end_dt, open_re_end_of_week.open_re_end_of_week_cnt, open_re_begin_of_week.open_re_begin_of_week_cnt, open_re_during_week.open_re_during_week_cnt, closed_re_during_week.closed_re_during_week_cnt, open_re_end_of_week.open_re_end_of_week_cnt - ( open_re_begin_of_week.open_re_begin_of_week_cnt + open_re_during_week.open_re_during_week_cnt - closed_re_during_week.closed_re_during_week_cnt ) as difference, CASE WHEN difference != 0 THEN 1 ELSE 0 END AS FAILED, 1 AS TOTAL from wk, ( select 1 as key, count(1) as open_re_end_of_week_cnt from core_dim.t_dim_real_estate_1 as re_1 join core_dim.t_fact_real_estate_lifecycle_1 as rel on re.real_estate_sid = rel.real_estate_sid, wk where wk.part_week_end_dt between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp and rel.open_dt <= wk.part_week_end_dt and rel.open_dt <> '0001-01-01' and ( rel.close_dt > wk.part_week_end_dt or rel.close_dt = '0001-01-01' ) ) open_re_end_of_week join ( select 1 as key, count(1) as open_re_begin_of_week_cnt from core_dim.t_dim_real_estate_1 as re_1 join core_dim.t_fact_real_estate_lifecycle_1 as rel on re.real_estate_sid = rel.real_estate_sid, wk where wk.part_week_begin_dt between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp and rel.open_dt <= dateadd(day,-1,wk.part_week_begin_dt) and rel.open_dt <> '0001-01-01' and ( rel.close_dt > wk.part_week_begin_dt or rel.close_dt = '0001-01-01' ) ) open_re_begin_of_week on open_re_end_of_week.key = open_re_begin_of_week.key join ( select 1 as key, count(1) as open_re_during_week_cnt from core_dim.t_dim_real_estate_1 as re_1 join core_dim.t_fact_real_estate_lifecycle_1 as rel on re.real_estate_sid = rel.real_estate_sid, wk where rel.open_dt between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp and rel.open_dt between wk.part_week_begin_dt and wk.part_week_end_dt ) open_re_during_week on open_re_during_week.key = open_re_begin_of_week.key join( select 1 as key, count(1) as closed_re_during_week_cnt from core_dim.t_dim_real_estate_1 as re_1 join core_dim.t_fact_real_estate_lifecycle_1 as rel on re.real_estate_sid = rel.real_estate_sid, wk where rel.close_dt between re.dwh_valid_from_tmsp and re.dwh_valid_to_tmsp and rel.close_dt between wk.part_week_begin_dt and wk.part_week_end_dt ) closed_re_during_week on closed_re_during_week.key = open_re_during_week.key;